static int get_ancillary2(spng_ctx *ctx)
{
    if(ctx == NULL) return 1;
    if(!ctx->valid_state) return SPNG_EBADSTATE;

    if(ctx->data == NULL) return 0;

    int ret;
    if(!ctx->first_idat.offset)
    {
        ret = read_chunks_before_idat(ctx);
        if(ret)
        {
            ctx->valid_state = 0;
            return ret;
        }
    }

    ctx->encode_only = 1;

